struct Distance
{
   int km;
   float m;
} d1, d2, result;

void convert (struct Distance * r)
{

   if (r->m > 1000.0)
   {
      r->m = r->m - 1000.0;
      r->km++;
   }
}
int main()
{
   printf("Enter 1st distance\n");
