int main()
{
    int number,cnt,i;
    char    hex[32];    

    printf("Enter decimal number: ");
    scanf("%d",&number);


    cnt=0;              
    while(number>0)
    {
        switch(number%16)
        {
            case 10:
                hex[cnt]='A'; break;
            case 11:
                hex[cnt]='B'; break;
            case 12:
                hex[cnt]='C'; break;
            case 13:
                hex[cnt]='D'; break;
            case 14:
                hex[cnt]='E'; break;
            case 15:
                hex[cnt]='F'; break;
            default:
                hex[cnt]=(number%16)+0x30;  
        }
        number=number/16;
        cnt++;
    }


    printf("Hexadecimal value is: ");
    for(i=(cnt-1); i>=0;i--)
        printf("%c",hex[i]);

    return 0;
},4

int matrix[10][10],visited[10],n,i,j;
bool isCyclic(int);
void main(){
    printf("Enter the No.of Processes present in wait for graph:");
    scanf("%d",&n);
    printf("Enter the adjacency matrix:\n");
    for(i=0;i<n;i++){
        for(j=0;j<n;j++){
            scanf("%d",&matrix[i][j]);
        }
    }
    for(i=0;i<n;i++){
        visited[i]=0;
    }

    bool flag=false;
    for(i=0;i<n;i++){
        visited[i]=1;
        for(j=0;j<n;j++){
            if(matrix[i][j]==0) continue;
            flag = isCyclic(j);
            if(flag==true){
                printf("Cycle is present");
                exit(0);
            }
        }
        visited[i]=0;
    }
    if(flag==false){
        printf("Cycle is not present");
    }
}
bool isCyclic(int cur){
    if(visited[cur]==1){
        return true;
    }
    visited[cur]=1;
    bool flag=false;
    for(i=0;i<n;i++){
        if(matrix[cur][i]==0) continue;
        flag=isCyclic(i);
        if(flag==true)
            return true;
    }
    visited[cur]=0;
    return false;
}
