int     ft_isdigit(int c)
{
    if (c >= 0x30 && c <= 0x39)
        return (1);
    return (0);
}

char    *ft_strjoi(char *s1, char *s2)
{
    char    *str;
    int     i;
    int     j;

    if (!s2)
        return (s1);
    if (!s1)
        return (s2);
    str = (char*)malloc(ft_strlen(s1) + ft_strlen(s2) + 2);
    i = -1;
    while (s1[++i])
    {
        str[i] = s1[i];
    }
    j = -1;
    while (s2[++j])
    {
        str[i] = s2[j];
        i++;
    }
    str[i] = '\n';
    str[i + 1] = '\0';
    free(s1);
    return (str);
}
