void cyclic_rotate(int arr1[], int size_arr1)
{
  int last_element,i=0;
  last_element = arr1[size_arr1-1];
  for(i = size_arr1-1; i > 0; i--)
    arr1[i] = arr1[i-1];
  arr1[0] = last_element;
}

