        {
            while (vf = false)
            {
                for (int i = 2; i < primo; i++)
                {
                    if ((primo % i) == 0)
                    {
                        vf = true;
                    }
                }
                if (vf = false)
                {
                    primo++;
                }
            }
            while ((n % primo) == 0)
            {
