static unsigned int crc_table[256];
const static char * program_name = "crc32";

static void usage(void);
static void init_crc_table(void);
static unsigned int crc32(unsigned char * buffer, unsigned int size);
static int calc_img_crc(const char * in_file, unsigned int * img_crc);

static void usage(void)
{
    fprintf(stderr, "Usage: %s input_file\n", program_name);
}


static void init_crc_table(void)
{
    unsigned int c;
    unsigned int i, j;

    for (i = 0; i < 256; i++) {
        c = (unsigned int)i;
        for (j = 0; j < 8; j++) {
            if (c & 1)
                c = 0xedb88320L ^ (c >> 1);
            else
                c = c >> 1;
        }
        crc_table[i] = c;
    }
}



unsigned int crc32_table[256];

void make_crc32_table() {
    unsigned int c;
    int i = 0;
    int bit = 0;

    for(i = 0; i < 256; i++)
    {
        c  = (unsigned int)i;

        for(bit = 0; bit < 8; bit++)
        {
            if(c&1)
            {
                c = (c >> 1)^(0xEDB88320);
            }
            else
            {
                c =  c >> 1;
            }

        }
        crc32_table[i] = c;
    }
}

unsigned int crc32lql(unsigned char *string, unsigned int size) {
    make_crc32_table();
    unsigned int crc = 0xffffffff;
    while(size--)
        crc = (crc >> 8)^(crc32_table[(crc ^ *string++)&0xff]);
    return crc;
}


static unsigned int crc32(unsigned char *buffer, unsigned int size)
{
    unsigned int crc = 0xFFFFFFFF;
    unsigned int i;
    for (i = 0; i < size; i++) {
        crc = crc_table[(crc ^ buffer[i]) & 0xff] ^ (crc >> 8);
    }
    return crc ;
}

unsigned int crc32cyy(unsigned char *data,int len) {
    unsigned int crc = 0xFFFFFFFF;
    int i;
    for (i=0;i<len;i++) {
        crc = crc ^ data[i];
        int j;
        for (j=7;j>=0;j--) {
            crc = (crc >> 1) ^ (0xEDB88320 & (-(crc & 1)));
        }
    }
    return ~crc;
}











































