#define size 5

typedef struct
{
    char queue[size];
    int front;
    int rear;

}que;

void insertq(que* pq, int item)
{
    if ((pq->front == 0 && pq->rear == size - 1) || (pq->front == pq->rear + 1))
    {
        printf("queue is full");
        return;
    }

    else if (pq->rear ==  -1)
    {
        pq->rear++;
        pq->front++;
    }

    else if (pq->rear == size - 1 && pq->front > 0)
    {
        pq->rear = 0;
    }

    else
    {
        pq->rear++;
    }

    pq->queue[pq->rear] = item;
}

void display(que* pq)
{
    int i;
    printf("\n");

    if (pq->front ==  -1)
    {
        printf("Queue is empty");
        return;
    }

    if (pq->front > pq->rear)
    {
        for (i = pq->front; i < size; i++)
            printf("%d ", pq->queue[i]);

        for (i = 0; i <= pq->rear; i++)
            printf("%d ", pq->queue[i]);
    }

    else
    {
        for (i = pq->front; i <= pq->rear; i++)
            printf("%d ", pq->queue[i]);
    }
}

void deleteq(que* pq)
{
    if (pq->front ==  -1)
        printf("Queue is empty");

    else if (pq->front == pq->rear)
    {
        printf("\n%d deleted", pq->queue[pq->front]);
        pq->front =  -1;
        pq->rear =  -1;
    }

    else if (pq->front == size-1) 
    {
        printf("\n%d deleted", pq->queue[pq->front]);
        pq->front = 0;
    }

    else
        printf("\n%d deleted", pq->queue[(pq->front)++]);

}

int main()
{
    int n, ch;
    que q;

    q.front = q.rear = -1;

    do
    {
        printf("\nCircular Queue:\n1. Insert \n2. Delete\n3. Display\n0. Exit");
        printf("\nEnter Choice 0-3? : ");
        scanf("%d", &ch);

        switch (ch)
        {
            case 1:
                printf("\nEnter number: ");
                scanf("%d", &n);
                insertq(&q, n);
                break;

            case 2:
                deleteq(&q);
                break;

            case 3:
                display(&q);
                break;
        }

    }while (ch != 0);
},62

node* mergeTwoLLs(node *head1, node *head2) 
{
    node* t1 = head1;
    node* t2 = head2;

    node* head;
    node* tail;

    if(head1->data <= head2->data)
    {
        head = head1;
        tail = head1;
        t1 = t1->next;
    }   
    else 
    {
        head = head2;  
        tail = head2;
        t2 = t2->next;
    }

    while(t1 != NULL && t2 != NULL)
        if(t1->data <= t2->data)
        {
            tail->next = t1;
            tail = t1;
            t1 = t1->next;
        }   
        else
        {
            tail->next = t2;
            tail = t2;
            t2 = t2->next;
        }

    if(t1 == NULL)
        tail->next = t2;

    else
        tail->next = t1;

    return head;
